pub struct Format;

impl Format {
    pub fn percentage(value: f32) -> String {
        Self::percentage_with_precision(value, 1)
    }

    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
        format_percentage(f64::from(value), precision)
    }
}

pub(crate) fn format_ratio(progress: usize, total: usize, precision: usize) -> String {
    if total == 0 {
        return format_percentage(0.0, precision);
    }

    format_percentage(progress as f64 / total as f64, precision)
}

fn format_percentage(value: f64, precision: usize) -> String {
    format!("{:.*}%", precision, value * 100.0)
}

#[cfg(test)]
mod tests {
    use super::{format_ratio, Format};

    #[test]
    fn formats_percentage_with_default_precision() {
        assert_eq!(Format::percentage(0.33_f32), "33.0%");
    }

    #[test]
    fn formats_percentage_with_custom_precision() {
        assert_eq!(Format::percentage_with_precision(0.66_f32, 2), "66.00%");
    }

    #[test]
    fn formats_ratio_with_one_decimal_place() {
        assert_eq!(format_ratio(1, 3, 1), "33.3%");
    }
}

