use crate::formatting::format_ratio;

pub struct ProgressBuilder {
    progress: usize,
    total: usize,
}

impl ProgressBuilder {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: usize) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: usize) -> &mut Self {
        self.total = total;
        self
    }

    pub fn build(&self) -> String {
        format_ratio(self.progress, self.total, 1)
    }
}

impl Default for ProgressBuilder {
    fn default() -> Self {
        Self {
            progress: 0,
            total: 100,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::ProgressBuilder;

    #[test]
    fn builds_percentage_output() {
        let mut builder = ProgressBuilder::new();
        builder.set_progress(60).set_total(200);
        assert_eq!(builder.build(), "30.0%");
    }
}

