use crate::formatting::format_ratio;

pub struct ProgressTracker {
    stages: Vec<String>,
    progress: usize,
    total: Option<usize>,
}

impl ProgressTracker {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_stage(&mut self, stage: &str) -> &mut Self {
        self.stages.push(stage.to_string());
        self
    }

    pub fn set_progress(&mut self, progress: usize) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: usize) -> &mut Self {
        self.total = Some(total);
        self
    }

    pub fn get_progress(&self) -> String {
        format!("{}/{}", self.progress, self.total())
    }

    pub fn get_percentage(&self) -> String {
        format_ratio(self.progress, self.total(), 1)
    }

    fn total(&self) -> usize {
        self.total.unwrap_or(self.stages.len())
    }
}

impl Default for ProgressTracker {
    fn default() -> Self {
        Self {
            stages: Vec::new(),
            progress: 0,
            total: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::ProgressTracker;

    #[test]
    fn reports_progress_and_percentage() {
        let mut tracker = ProgressTracker::new();
        tracker
            .add_stage("Downloading")
            .add_stage("Processing")
            .add_stage("Saving");
        tracker.set_progress(1).set_total(3);

        assert_eq!(tracker.get_progress(), "1/3");
        assert_eq!(tracker.get_percentage(), "33.3%");
    }
}

